        tokens = sentence.split()
        valid_count = 0
        punctuation_marks = set(['!', '.', ','])
        for token in tokens:
            if any(ch.isdigit() for ch in token):
                continue
            hyphen_count = token.count('-')
            if hyphen_count > 1:
                continue
            if hyphen_count == 1:
