                if hyphen_index == 0 or hyphen_index == len(token) - 1:
                    continue
                if not (token[hyphen_index - 1].islower() and token[hyphen_index + 1].islower()):
                    continue
            punctuation_count = sum(1 for ch in token if ch in punctuation_marks)
            if punctuation_count > 1:
                continue
            if punctuation_count == 1 and token[-1] not in punctuation_marks:
                continue
            valid_count += 1
        return valid_count"}
